	*ctx = ctx_init;
	assert (plugin_ctx_key_initialized);
	pthread_setspecific (plugin_ctx_key, ctx);
	DEBUG("Created new plugin context.");
	return (ctx);
} /* int plugin_ctx_create */

static _Bool check_drop_value (void) /* {{{ */ /* <=== check_drop_value */ 
{
	static cdtime_t last_message_time = 0;
	static pthread_mutex_t last_message_lock = PTHREAD_MUTEX_INITIALIZER;

	double p;
	double q;
	int status;

	if (write_limit_high == 0)
		return (0);

	p = get_drop_probability ();
	if (p == 0.0)
		return (0);

	status = pthread_mutex_trylock (&last_message_lock);
	if (status == 0)
	{
		cdtime_t now;

		now = cdtime ();
		if ((now - last_message_time) > TIME_T_TO_CDTIME_T (1))
		{
			last_message_time = now;
			ERROR ("plugin_dispatch_values: Low water mark "
					"reached. Dropping %.0f%% of metrics.",
					100.0 * p);
		}
		pthread_mutex_unlock (&last_message_lock);
	}

	if (p == 1.0)
		return (1);

	q = cdrand_d ();
	if (q > p)
		return (1);
	else
		return (0);
} /* }}} _Bool check_drop_value */

static char *md_strdup (const char *orig) /* {{{ */ /* <=== md_strdup */ 
{
  size_t sz;
  char *dest;

  if (orig == NULL)
    return (NULL);

  sz = strlen (orig) + 1;
  dest = (char *) malloc (sz);
  if (dest == NULL)
    return (NULL);

  memcpy (dest, orig, sz);

  return (dest);
} /* }}} char *md_strdup */

static int parse_part_sign_sha256 (sockent_t *se, /* {{{ */ /* <=== parse_part_sign_sha256 */ 
    void **ret_buffer, size_t *ret_buffer_size, int flags)
{
  static int warning_has_been_printed = 0;

  char *buffer;
  size_t buffer_size;
  size_t buffer_offset;
  uint16_t part_len;

  part_signature_sha256_t pss;

  buffer = *ret_buffer;
  buffer_size = *ret_buffer_size;
  buffer_offset = 0;

  if (buffer_size <= PART_SIGNATURE_SHA256_SIZE)
    return (-ENOMEM);

  BUFFER_READ (&pss.head.type, sizeof (pss.head.type));
  BUFFER_READ (&pss.head.length, sizeof (pss.head.length));
  part_len = ntohs (pss.head.length);

  if ((part_len <= PART_SIGNATURE_SHA256_SIZE)
      || (part_len > buffer_size))
    return (-EINVAL);

  if (warning_has_been_printed == 0)
  {
    WARNING ("network plugin: Received signed packet, but the network "
        "plugin was not linked with libgcrypt, so I cannot "
        "verify the signature. The packet will be accepted.");
    warning_has_been_printed = 1;
  }

  parse_packet (se, buffer + part_len, buffer_size - part_len, flags,
      /* username = */ NULL);

  *ret_buffer = buffer + buffer_size;
  *ret_buffer_size = 0;

  return (0);
} /* }}} int parse_part_sign_sha256 */

static int network_dispatch_values (value_list_t *vl, /* {{{ */ /* <=== network_dispatch_values */ 
    const char *username)
{
  int status;

  if ((vl->time <= 0)
      || (strlen (vl->host) <= 0)
      || (strlen (vl->plugin) <= 0)
      || (strlen (vl->type) <= 0))
    return (-EINVAL);

  if (!check_receive_okay (vl))
  {
#if COLLECT_DEBUG
    char name[6*DATA_MAX_NAME_LEN];
    FORMAT_VL (name, sizeof (name), vl);
    name[sizeof (name) - 1] = 0;
    DEBUG ("network plugin: network_dispatch_values: "
	"NOT dispatching %s.", name);
#endif
    stats_values_not_dispatched++;
    return (0);
  }

  assert (vl->meta == NULL);

  vl->meta = meta_data_create ();
  if (vl->meta == NULL)
  {
    ERROR ("network plugin: meta_data_create failed.");
    return (-ENOMEM);
  }

  status = meta_data_add_boolean (vl->meta, "network:received", 1);
  if (status != 0)
  {
    ERROR ("network plugin: meta_data_add_boolean failed.");
    meta_data_destroy (vl->meta);
    vl->meta = NULL;
    return (status);
  }

  if (username != NULL)
  {
    status = meta_data_add_string (vl->meta, "network:username", username);
    if (status != 0)
    {
      ERROR ("network plugin: meta_data_add_string failed.");
      meta_data_destroy (vl->meta);
      vl->meta = NULL;
      return (status);
    }
  }

  plugin_dispatch_values (vl);
  stats_values_dispatched++;

  meta_data_destroy (vl->meta);
  vl->meta = NULL;

  return (0);
} /* }}} int network_dispatch_values */

