static char *sstrerror (int errnum, char *buf, size_t buflen) /* <=== sstrerror */ 
{
  buf[0] = 0;

#if !HAVE_STRERROR_R
  snprintf (buf, buflen, "Error #%i; strerror_r is not available.", errnum);
/* #endif !HAVE_STRERROR_R */

#elif STRERROR_R_CHAR_P
  {
    char *temp;
    temp = strerror_r (errnum, buf, buflen);
    if (buf[0] == 0)
    {
      if ((temp != NULL) && (temp != buf) && (temp[0] != 0))
        strncpy (buf, temp, buflen);
      else
        strncpy (buf, "strerror_r did not return "
            "an error message", buflen);
    }
  }
/* #endif STRERROR_R_CHAR_P */

#else
  if (strerror_r (errnum, buf, buflen) != 0)
  {
    snprintf (buf, buflen, "Error #%i; "
        "Additionally, strerror_r failed.",
        errnum);
  }
#endif /* STRERROR_R_CHAR_P */

  buf[buflen - 1] = 0;

  return (buf);
} /* char *sstrerror */

int plugin_dispatch_notification (const notification_t *notif) /* <=== plugin_dispatch_notification */ 
{
	llentry_t *le;
	/* Possible TODO: Add flap detection here */

	DEBUG ("plugin_dispatch_notification: severity = %i; message = %s; "
			"time = %.3f; host = %s;",
			notif->severity, notif->message,
			CDTIME_T_TO_DOUBLE (notif->time), notif->host);

	/* Nobody cares for notifications */
	if (list_notification == NULL)
		return (-1);

	le = llist_head (list_notification);
	while (le != NULL)
	{
		callback_func_t *cf;
		plugin_notification_cb callback;
		int status;

		/* do not switch plugin context; rather keep the context
		 * (interval) information of the calling plugin */

		cf = le->value;
		callback = cf->cf_callback;
		status = (*callback) (notif, &cf->cf_udata);
		if (status != 0)
		{
			WARNING ("plugin_dispatch_notification: Notification "
					"callback %s returned %i.",
					le->key, status);
		}

		le = le->next;
	}

	return (0);
} /* int plugin_dispatch_notification */

