static int plugin_write_enqueue (value_list_t const *vl) /* {{{ */ /* <=== plugin_write_enqueue */ 
{
	write_queue_t *q;

	q = malloc (sizeof (*q));
	if (q == NULL)
		return (ENOMEM);
	q->next = NULL;

	q->vl = plugin_value_list_clone (vl);
	if (q->vl == NULL)
	{
		sfree (q);
